cd "$ARCHON_HORIZON_ROOT" && "$HORIZON_BIN" usage --json 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
for k in ('paused','recent_failure_reasons'):
    print(k,d.get(k))
s=d.get('session') or {}
print('session',{k:s.get(k) for k in list(s)[:12]})
r=d.get('run') or {}
print('run',{k:r.get(k) for k in list(r)[:12]})
b=d.get('budget') or {}
print('budget',b)
"
